def choose_move(observation):
    x, y = observation['self_position']
    w, h = observation['grid_width'], observation['grid_height']
    obstacles = set(observation.get('obstacles', []))
    resources = observation.get('resources', [])
    opponent_x, opponent_y = observation.get('opponent_position', (x,y))
    def dist(a,b): return abs(a[0]-b[0])+abs(a[1]-b[1])
    # Determine possible moves
    directions = {'RIGHT':(1,0), 'LEFT':(-1,0), 'DOWN':(0,1), 'UP':(0,-1)}
    safe_moves = []
    for name, (dx,dy) in directions.items():
        nx, ny = x+dx, y+dy
        if 0 <= nx < w and 0 <= ny < h and (nx,ny) not in obstacles:
            safe_moves.append((dx,dy))
    if not safe_moves:
        return [0,0]
    # Prioritize moving toward nearest resource
    if resources:
        resource = min(resources, key=lambda r: dist((x+directions['RIGHT'][0], y+directions['RIGHT'][1]), r))
        target = resource
    else:
        target = (x, y)
    # Choose move that minimizes distance to target
    best_move = None
    min_dist = float('inf')
    for dx,dy in safe_moves:
        nx, ny = x+dx, y+dy
        d = dist((nx, ny), target)
        # Avoid moving onto opponent
        if (nx, ny) == (opponent_x, opponent_y):
            continue
        if d < min_dist:
            min_dist = d
            best_move = [dx, dy]
    if best_move is None:
        best_move = [0,0]
    return best_move
